export { anatomy, parts, type SearchFieldPart } from "./search-field.anatomy";
export { connect } from "./search-field.connect";
export {
  getCancelTriggerId,
  getClearTriggerId,
  getControlEl,
  getControlId,
  getFieldId,
  getIndicatorId,
  getRootId,
} from "./search-field.dom";
export { isSearchHotkey } from "./search-field.hotkey";
export { machine } from "./search-field.machine";
export type {
  ResolvedSearchFieldMachineProps,
  SearchFieldApi,
  SearchFieldMachineProps,
  SearchFieldSchema,
  SearchFieldShape,
  SearchFieldValueChangeDetails,
  SearchHotkeyPredicate,
} from "./search-field.types";

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./search-field.anatomy";
import {
  getCancelTriggerId,
  getClearTriggerId,
  getControlId,
  getFieldId,
  getIndicatorId,
  getRootId,
} from "./search-field.dom";
import type { SearchFieldApi, SearchFieldSchema } from "./search-field.types";

export function connect<T extends PropTypes>(
  service: Service<SearchFieldSchema>,
  normalize: NormalizeProps<T>,
): SearchFieldApi<T> {
  const { context, prop, state, send, scope } = service;

  const value = context.get("value");
  const empty = value === "";
  const disabled = prop("disabled");
  const invalid = prop("invalid");
  const readOnly = prop("readOnly");
  const label = prop("label");
  const focused = state.matches("focused");
  // The source is read once, when focus lands, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = focused ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const stateAttrs = {
    "data-disabled": dataAttr(disabled),
    "data-invalid": dataAttr(invalid),
    "data-readonly": dataAttr(readOnly),
    "data-focus-visible": dataAttr(focusVisible),
    "data-focus-source": focusSource ?? undefined,
    // Not `data-snav-focused`: that attribute belongs to `@standarx/nav`'s spatial
    // engine, and the styles hang the tvOS lift off it.
    "data-focus": dataAttr(focused),
  };

  return {
    value,
    empty,
    disabled,
    invalid,
    focusSource,
    focusVisible,

    setValue(next: string): void {
      send({ type: "VALUE.SET", value: next });
    },
    clear(): void {
      send({ type: "VALUE.CLEAR" });
    },
    cancel(): void {
      send({ type: "VALUE.CANCEL" });
    },

    // The ROW, and the landmark — not the box. The capsule moved to `field` on
    // 2026-09-05 so the cancel button could stand beside it rather than inside
    // it, which is the only arrangement in practice.
    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        // Kept here as well as on `field`: the row fades as one thing, the
        // cancel button included, and `[data-disabled]` is the single rule that
        // stayed on the root when the box left.
        ...stateAttrs,
        id: getRootId(scope),
        dir: prop("dir"),
        // The landmark, which is the whole normative recipe for search: there is
        // no APG "search" pattern, there is `role="search"` around a native
        // `searchbox`. Named by `label`, because two unnamed search landmarks on
        // one page are indistinguishable to anyone using a landmark list.
        role: "search",
        "aria-label": label,
        // The row lays itself out on this — the button is rendered or it is not.
        "data-empty": dataAttr(empty),
      }),

    // The CAPSULE: the box, the border, the radius, the ring, the wash. The two
    // presentation tokens travel with it, because they describe a box and the box
    // is here now. A consumer's own sheet keyed on `[data-variant="search"]` keeps
    // matching — that selector never named a part.
    getFieldProps: (): T["element"] =>
      normalize.element({
        ...parts.field.attrs,
        ...stateAttrs,
        id: getFieldId(scope),
        "data-variant": "search",
        "data-shape": prop("shape"),
        "data-empty": dataAttr(empty),
      }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        // Decorative: the landmark and the placeholder already say "search", and
        // a magnifier announced beside them is one repetition too many.
        "aria-hidden": "true",
      }),

    getControlProps: (): T["input"] =>
      normalize.input({
        ...parts.control.attrs,
        ...stateAttrs,
        id: getControlId(scope),
        dir: prop("dir"),
        // Never a `role`: `input[type=search]` *is* a `searchbox`, and writing the
        // role by hand is how a native one gets overridden with a worse copy.
        type: "search",
        value,
        disabled,
        readOnly,
        required: prop("required"),
        name: prop("name"),
        form: prop("form"),
        placeholder: prop("placeholder"),
        maxLength: prop("maxLength"),
        autoComplete: prop("autoComplete"),
        // A phone keyboard gets its search key from this; a `field`'s visible
        // label still wins the name calculation over the `aria-label` below.
        inputMode: prop("inputMode") ?? "search",
        "aria-label": label,
        "aria-invalid": ariaAttr(invalid),
        "aria-describedby": prop("describedBy"),
        onInput(event: Event) {
          if (event.defaultPrevented) return;
          const target = event.target as HTMLInputElement | null;
          if (target !== null) send({ type: "VALUE.SET", value: target.value });
        },
        onKeyDown(event: KeyboardEvent) {
          if (event.defaultPrevented || event.key !== "Escape" || !prop("clearOnEscape")) return;
          // Only when there is something to clear: an empty field lets Escape
          // through to whatever is above it — that is the "then closes" of the
          // annexe, and it belongs to the popover, not to the field.
          if (empty) return;
          event.preventDefault();
          send({ type: "VALUE.CLEAR" });
        },
        onFocus(event: FocusEvent) {
          if (event.defaultPrevented) return;
          send({ type: "CONTROL.FOCUS" });
        },
        onBlur(event: FocusEvent) {
          if (event.defaultPrevented) return;
          send({ type: "CONTROL.BLUR" });
        },
      }),

    getClearTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.clearTrigger.attrs,
        // Deliberately not `stateAttrs`: the field's focus state would ring this
        // button whenever the caret is in the control.
        "data-disabled": dataAttr(disabled),
        "data-invalid": dataAttr(invalid),
        id: getClearTriggerId(scope),
        type: "button",
        // Out of the tab order, and not by omission. native desktop fields do not put it in the
        // keyboard path, Escape is the keyboard way to clear, and a tab stop that
        // evaporates the moment it does its job drops the focus on `<body>`. It
        // keeps a name and stays in the a11y tree, so an AT user activates it
        // without ever focusing it.
        tabIndex: -1,
        // And out of the *pad's* path too, which `tabIndex` alone does not buy:
        // the spatial engine scores every focusable, and `tabindex="-1"` is
        // still focusable. Without this, `moveRight` from the control lands on
        // the clear button — measured, 2026-09-05 — and a d-pad would reach a
        // control no arrow key can, which is the one thing CDC §4.4 forbids
        // outright ("clavier fléché et d-pad produisent les mêmes intents").
        // The precedent is `toast:group`, which excludes itself the same way.
        "data-snav-ignore": "",
        disabled,
        // The rule: a disabled field
        // with text in it keeps the glyph hidden.
        hidden: empty || disabled || readOnly,
        "aria-label": prop("clearLabel"),
        "aria-controls": getControlId(scope),
        // Like the eye on a password field: a mouse press must not take the caret
        // out of the control.
        onMouseDown(event) {
          if (event.defaultPrevented) return;
          event.preventDefault();
        },
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLEAR.CLICK" });
        },
      }),

    getCancelTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.cancelTrigger.attrs,
        // Deliberately not `stateAttrs`, for the clear button's reason: the
        // field's focus state would ring this button whenever the caret is in
        // the control. Its own ring comes from the page's modality instead.
        "data-disabled": dataAttr(disabled || readOnly),
        "data-invalid": dataAttr(invalid),
        id: getCancelTriggerId(scope),
        type: "button",
        // No `tabIndex`, and that is the difference from the clear button rather
        // than an oversight. The clear button has Escape as its keyboard double,
        // so taking it out of the tab order costs nothing; this one has no
        // double at all, so removing it would be a 2.1.1 failure. The focus it
        // drops when it goes is answered with an action instead of an
        // amputation — `focusControl` on the gesture, `rescueCancelFocus` when
        // somebody else empties the field.
        disabled: disabled || readOnly,
        // Rendered but inert while read-only: `CANCEL.CLICK` empties the value,
        // which read-only forbids. Either it does its job or it says it cannot —
        // never "it vanished for no visible reason". Only emptiness takes it
        // away, because only emptiness re-lays-out the row.
        hidden: empty,
        "aria-label": prop("cancelLabel"),
        "aria-controls": getControlId(scope),
        // Like the clear button and the eye on a password field: a mouse press
        // must not take the caret out of the control. It is also what keeps
        // `cancelFocused` true only for a keyboard or a pad.
        onMouseDown(event) {
          if (event.defaultPrevented) return;
          event.preventDefault();
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.BLUR" });
        },
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.CLICK" });
        },
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "search-field";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getFieldId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "field");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getClearTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "clearTrigger");
}

export function getCancelTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "cancelTrigger");
}

export function getControlEl(scope: Scope): HTMLElement | null {
  return scope.getById(getControlId(scope));
}

/**
 * The activation shortcut, as a predicate the consumer opts into.
 *
 * Taking ⌘F away from the browser is an application's decision, never a
 * library's default: on a page whose search covers the whole content it is
 * exactly right, and on a page with one filter box in a corner it removes
 * find-in-page for no gain. So the machine ships the predicate and installs
 * nothing until it is handed one.
 */

import { isHTMLElement } from "../../dom/query";

/** ⌘F where the Command key exists, Ctrl+F elsewhere — and never both modifiers, which is Emacs. */
export function isSearchHotkey(event: KeyboardEvent): boolean {
  if (event.altKey || event.shiftKey) return false;
  // Exactly one of the two: Ctrl+⌘+F is a different chord, and a keyboard event
  // with neither is a plain "f" the user is typing.
  if (event.metaKey === event.ctrlKey) return false;
  return event.key.toLowerCase() === "f";
}

/**
 * Anything a caret can be in. A global shortcut that fires while somebody is
 * typing somewhere else steals their keystroke — Ctrl+F is caret-forward in
 * native desktop text fields and in every Emacs binding — so the listener steps aside for those.
 */
export function isEditableTarget(target: EventTarget | null): boolean {
  if (!isHTMLElement(target)) return false;
  if (target.isContentEditable) return true;
  const tag = target.localName;
  return tag === "input" || tag === "textarea" || tag === "select";
}

/**
 * The search presentation of a text field: the same value handling as `input`,
 * plus the four things that only make sense for search — Escape empties the
 * field, a clear button that takes the focus back with it, a cancel button that
 * stands *outside* the capsule and says so to the consumer, and an opt-in
 * activation shortcut.
 *
 * Cancelling is clearing plus a notification, never a substitute for one: a
 * consumer filtering on `onValueChange` has to see the empty string or their
 * list stays filtered. What `onCancel` buys is the intention, which survives a
 * field that was already empty — and being fired last, so a consumer who moves
 * the focus inside it wins against the focus this machine hands back.
 *
 * It carries its own scope rather than riding `input`'s parts, and the reason is
 * the composition rule, not taste: `search-field:clear-trigger` and
 * `search-field:indicator` are parts of this presentation, and a consumer who
 * styles them must not have to know they were spelled `input:*`. What the two
 * share — the field box, the ring, the shapes, the disabled wash — is shared
 * through the tokens, which is where sharing costs nothing.
 *
 * The DOM's own value is the source of truth while typing; the machine only
 * records what the browser reports.
 */

import { getEventTarget } from "../../dom/query";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getControlEl } from "./search-field.dom";
import { isEditableTarget } from "./search-field.hotkey";
import type { SearchFieldSchema } from "./search-field.types";

export const machine: Machine<SearchFieldSchema> = createMachine<SearchFieldSchema>({
  props({ props }) {
    return {
      shape: "capsule",
      disabled: false,
      invalid: false,
      readOnly: false,
      required: false,
      // The one default that differs from `input`, and the one that makes this a
      // search field: native platforms empty the field on Escape. It still only
      // consumes the key when there is something to empty (see `connect`).
      clearOnEscape: true,
      // **Defaulted, unlike the field's own label, and the asymmetry is the
      // point.** A search field with no label has an alternative path — compose it
      // into `field`, which names it — so the library declines to invent one. The
      // clear button has none: rendered without this, it is an icon-only
      // `<button>` with an `aria-hidden` glyph and no accessible name at all,
      // which axe grades `button-name` and WCAG 2.2 grades a level A failure. The
      // library already ships English here for exactly this reason —
      // `breadcrumb.ellipsisLabel` and pagination's three — and a wrong-language
      // name is recoverable where an absent one is not.
      clearLabel: "Clear search",
      // Same argument, and stronger: the clear button is out of the tab order,
      // this one is a tab stop a keyboard user arrives at head-on. An unnamed
      // `<button>` there is a level A failure nobody can route around.
      cancelLabel: "Cancel search",
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<string>(() => ({
        defaultValue: prop("defaultValue") ?? "",
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "search-field value",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  refs() {
    return { cancelFocused: false };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackHotkey"],

  // The cancel button is a tab stop that disappears the moment the field goes
  // empty, so somebody else emptying it — a controlled `value=""`, `api.clear()`
  // — drops the focus on `<body>`. Played post-render by the adapter (the
  // DOM-before-watch hard rule), and the decision is read off the ref rather than
  // off `activeElement`: by the time this runs the button is already gone, so the
  // DOM no longer remembers that the focus was ever ours.
  watch({ context, track, action }) {
    track(
      () => [context.get("value")],
      () => action(["rescueCancelFocus"]),
    );
  },

  on: {
    "VALUE.SET": { guard: "isInteractive", actions: ["setValue"] },
    "VALUE.CLEAR": { guard: "isInteractive", actions: ["clearValue"] },
    // `api.cancel()`: the same asymmetry `VALUE.CLEAR` has against `CLEAR.CLICK`
    // — it empties and says so, and it takes nobody's caret. On an already-empty
    // field the bindable short-circuits, so `onValueChange` stays silent and
    // `onCancel` still fires: cancelling is an intention, not a change of value.
    "VALUE.CANCEL": { guard: "isInteractive", actions: ["clearValue", "notifyCancel"] },
    // Distinct from `VALUE.CLEAR` on purpose: `api.clear()` must not steal the
    // focus, and the gesture on the button must hand it back — the button is
    // about to disappear, and a focus left on a removed node lands on `<body>`.
    "CLEAR.CLICK": { guard: "isInteractive", actions: ["clearValue", "focusControl"] },
    // Cancelling is clearing plus a word about it, and the order matters:
    // `notifyCancel` is LAST so that a consumer who moves the focus inside
    // `onCancel` keeps it against `focusControl`, which has already run.
    "CANCEL.CLICK": {
      guard: "isInteractive",
      actions: ["clearValue", "focusControl", "notifyCancel"],
    },
    // No target on either: whether that button holds the focus is not a state of
    // this field, and nothing in the sheet is keyed on it.
    "CANCEL.FOCUS": { actions: ["markCancelFocused"] },
    "CANCEL.BLUR": { actions: ["clearCancelFocused"] },
    "CONTROL.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource"],
      on: { "CONTROL.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    },

    actions: {
      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },
      clearValue({ context }) {
        context.set("value", "");
      },
      focusControl({ scope }) {
        getControlEl(scope)?.focus();
      },
      notifyCancel({ prop }) {
        prop("onCancel")?.();
      },
      markCancelFocused({ refs }) {
        refs.set("cancelFocused", true);
      },
      clearCancelFocused({ refs }) {
        refs.set("cancelFocused", false);
      },
      rescueCancelFocus({ context, refs, scope }) {
        // Nothing to rescue unless the button was holding the focus *and* the
        // value that just changed went empty — which is exactly when the button
        // stops being rendered. A field that merely lost a character keeps it.
        if (!refs.get("cancelFocused") || context.get("value") !== "") return;
        refs.set("cancelFocused", false);
        getControlEl(scope)?.focus();
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackHotkey({ prop, scope }) {
        const match = prop("hotkey");
        // Not an optimisation: a page that did not ask for the shortcut keeps
        // find-in-page, and pays zero listeners for the field it never bound.
        if (match === undefined) return;

        const doc = scope.getDoc();
        const onKeyDown = (event: KeyboardEvent): void => {
          if (event.defaultPrevented || !match(event)) return;
          if (prop("disabled") || prop("readOnly")) return;

          const control = getControlEl(scope);
          if (control === null) return;

          // Somebody typing in another field keeps their keystroke: Ctrl+F is
          // caret-forward in native desktop text fields and in Emacs bindings alike.
          const target = getEventTarget(event);
          if (target !== control && isEditableTarget(target)) return;

          // Taking the browser's find-in-page is the contract of the opt-in, not
          // a side effect of it.
          event.preventDefault();
          control.focus();
          // ⌘F on an already-filled field retypes rather than appends, which is
          // what native desktop fields do with their own.
          if (control instanceof scope.getWin().HTMLInputElement) control.select();
        };

        // Capture, and installed natively rather than through a part's props:
        // both are hard rules, and capture is what lets the field answer before
        // an overlay swallows the key.
        doc.addEventListener("keydown", onKeyDown, true);
        return () => doc.removeEventListener("keydown", onKeyDown, true);
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

export interface SearchFieldValueChangeDetails {
  readonly value: string;
}

/**
 * How the field is drawn (CDC §4.2, amendment of 2026-08-31). `capsule` is the
 * default and the shape search is drawn with; `rect` is the
 * rounded rect, `soft` the value between the two. Search keeps its own inline
 * inset whichever shape it wears — the inset is what the search presentation
 * settles, the shape is a design choice no component can make for a consumer.
 */
export type SearchFieldShape = "capsule" | "soft" | "rect";

/**
 * Whether a keydown is the shortcut that focuses this field. A predicate rather
 * than a key descriptor: "the search shortcut" is ⌘F here, `/` there, and an app
 * that ships both should not have to file the difference with us.
 */
export type SearchHotkeyPredicate = (event: KeyboardEvent) => boolean;

export interface SearchFieldMachineProps {
  readonly dir?: Direction | undefined;
  readonly value?: string | undefined;
  readonly defaultValue?: string | undefined;
  readonly shape?: SearchFieldShape | undefined;
  readonly placeholder?: string | undefined;
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly required?: boolean | undefined;
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  readonly autoComplete?: string | undefined;
  /** Defaults to `search`, which is what puts a search key on a phone keyboard. */
  readonly inputMode?: string | undefined;
  readonly maxLength?: number | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /**
   * The accessible name of the control *and* of the `search` landmark. Never
   * defaulted to a string: a library that ships "Search" ships it in English.
   */
  readonly label?: string | undefined;
  /**
   * The accessible name of the clear button. Defaults to `"Clear search"` —
   * the one string this component ships, because the alternative is an icon-only
   * button with no name at all (see the machine for why this and `label` differ).
   */
  readonly clearLabel?: string | undefined;
  /**
   * The accessible name of the cancel button. Defaults to `"Cancel search"`, for
   * the same reason `clearLabel` is defaulted — and the reason is stronger here:
   * the clear button is out of the tab order, this one is a tab stop a keyboard
   * user meets head-on.
   */
  readonly cancelLabel?: string | undefined;
  /**
   * Escape empties the field. On by default here — that is the whole difference
   * between this presentation and a text field — and it only ever consumes the
   * key when there is something to clear.
   */
  readonly clearOnEscape?: boolean | undefined;
  /**
   * Opt-in activation shortcut, read once when the effect installs: pass it at
   * mount. Absent means no document listener at all, which is why a page that
   * did not ask keeps the browser's own find-in-page intact.
   */
  readonly hotkey?: SearchHotkeyPredicate | undefined;
  readonly onValueChange?: ((details: SearchFieldValueChangeDetails) => void) | undefined;
  /**
   * The cancel gesture happened. It is an **addition** to `onValueChange` and
   * never a replacement — the value went to the empty string, and a consumer
   * filtering on the value has to see that or their list stays filtered — and it
   * is fired **last**, after the focus has gone back to the control. That order
   * is the contract: `onCancel` is the last word, so a consumer who moves the
   * focus inside it (closing a search popover, say) keeps it.
   *
   * `api.cancel()` on an already-empty field fires this and *not*
   * `onValueChange`: cancelling is an intention, not a change of value.
   */
  readonly onCancel?: (() => void) | undefined;
}

export interface ResolvedSearchFieldMachineProps extends SearchFieldMachineProps {
  readonly shape: SearchFieldShape;
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
  readonly clearOnEscape: boolean;
}

export interface SearchFieldSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedSearchFieldMachineProps;
  context: { value: string; focusSource: InputModality | null };
  /**
   * Whether the cancel button is the thing holding the focus. A ref and not a
   * bindable on purpose: no rule in the sheet reads it, and making it context
   * would turn every focus of that button into a transition, a notification and
   * an adapter render for a fact nobody paints — the same arbitration
   * `data-scroll` makes. It is also why `cancelTrigger` carries no
   * `data-focus-visible`: its ring comes from the page's modality.
   */
  refs: { cancelFocused: boolean };
  event:
    | { type: "VALUE.SET"; value: string }
    | { type: "VALUE.CLEAR" }
    /**
     * The programmatic half of the cancel gesture. It exists for the reason
     * `VALUE.CLEAR` exists next to `CLEAR.CLICK`: `api.cancel()` must empty and
     * notify without taking anybody's caret, and `CANCEL.CLICK` hands the focus
     * back on purpose. One event cannot be both.
     */
    | { type: "VALUE.CANCEL" }
    | { type: "CLEAR.CLICK" }
    | { type: "CANCEL.CLICK" }
    | { type: "CANCEL.FOCUS" }
    | { type: "CANCEL.BLUR" }
    | { type: "CONTROL.FOCUS" }
    | { type: "CONTROL.BLUR" };
  action:
    | "setValue"
    | "clearValue"
    | "focusControl"
    | "notifyCancel"
    | "markCancelFocused"
    | "clearCancelFocused"
    | "rescueCancelFocus"
    | "captureFocusSource"
    | "clearFocusSource";
  guard: "isInteractive";
  effect: "trackModality" | "trackHotkey";
}

export interface SearchFieldApi<T extends PropTypes = PropTypes> {
  readonly value: string;
  /** What `data-empty` says on the root, for a consumer that needs it in script. */
  readonly empty: boolean;
  readonly disabled: boolean;
  readonly invalid: boolean;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  setValue(value: string): void;
  /** The programmatic clear: it empties the field and leaves the focus alone. */
  clear(): void;
  /**
   * The programmatic cancel: it empties the field, notifies `onCancel`, and — like
   * `clear()` — takes nobody's focus. On an already-empty field it still fires
   * `onCancel` and does not fire `onValueChange`.
   */
  cancel(): void;
  getRootProps(): T["element"];
  getFieldProps(): T["element"];
  getIndicatorProps(): T["element"];
  getControlProps(): T["input"];
  getClearTriggerProps(): T["button"];
  getCancelTriggerProps(): T["button"];
}

/**
 * `<SearchField icon={…}/>` — six parts, no loop, no state of its own: the row,
 * the capsule inside it, the two decorations the capsule carries, and the
 * cancel button that stands *beside* the capsule rather than in it.
 *
 * Unlike `input`, the two triggers already have names: `clearLabel` and
 * `cancelLabel` are machine props read straight off `search-field.connect.ts`
 * (`"Clear search"` / `"Cancel search"` by default), so they travel through
 * `root` untouched — this layer only places the button, it never invents the
 * word that names it.
 *
 * `cancel` is a boolean and not a `ComposedTrigger`-shaped substitution,
 * because there is nothing to substitute: `SearchFieldCancelTrigger` is
 * already a `<button>`, and what the reference designs disagree on is whether it exists at
 * all — touch layouts draw it beside the capsule, desktop layouts do not draw
 * it at all. The machine already decides *when* it is visible (`hidden` flips
 * on the empty/non-empty edge); `cancel` decides whether it is composed into
 * the tree in the first place, which is a decision the machine has no prop for
 * and should not — a field with no cancel button behaves identically to one
 * whose button happens to render `hidden`, so there is no state to duplicate.
 *
 * `icon` is the one slot: the leading glyph of the capsule, decorative by the
 * indicator's own contract (`aria-hidden`, set by `connect` regardless of
 * whether anything is passed here). Left out, no `SearchFieldIndicator`
 * renders at all, on `SelectItemSymbol`'s precedent — an empty decorative box
 * is not a shape either reference design draws.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  SearchFieldCancelTrigger,
  SearchFieldClearTrigger,
  SearchFieldControl,
  SearchFieldField,
  SearchFieldIndicator,
  SearchFieldRoot,
  type UseSearchFieldProps,
} from "./search-field";

/** The escape hatch, applied last on every part `root` is not reachable through: its own props are the composed props themselves. */
export interface SearchFieldParts {
  readonly field?: PartProps<"div"> | undefined;
  readonly indicator?: PartProps<"span"> | undefined;
  readonly control?: PartProps<"input"> | undefined;
  readonly clearTrigger?: PartProps<"button"> | undefined;
  readonly cancelTrigger?: PartProps<"button"> | undefined;
}

export interface SearchFieldComposedProps
  extends UseSearchFieldProps,
    Omit<PartProps<"div", UseSearchFieldProps>, "children"> {
  /** The leading glyph of the capsule — an inline SVG, never a text character. */
  readonly icon?: ReactNode;
  /** Composes the cancel button beside the capsule. Off by default: desktop layouts draw none. */
  readonly cancel?: boolean | undefined;
  readonly parts?: SearchFieldParts | undefined;
}

export function SearchField(props: SearchFieldComposedProps): ReactNode {
  const { icon, cancel, parts, ...root } = props;

  return (
    <SearchFieldRoot {...root}>
      <SearchFieldField {...parts?.field}>
        {icon === undefined ? null : (
          <SearchFieldIndicator {...parts?.indicator}>{icon}</SearchFieldIndicator>
        )}
        <SearchFieldControl {...parts?.control} />
        <SearchFieldClearTrigger {...parts?.clearTrigger} />
      </SearchFieldField>
      {cancel === true ? <SearchFieldCancelTrigger {...parts?.cancelTrigger} /> : null}
    </SearchFieldRoot>
  );
}

export {
  isSearchHotkey,
  type SearchFieldMachineProps,
  type SearchFieldShape,
  type SearchFieldValueChangeDetails,
  type SearchHotkeyPredicate,
} from "@standarui/core/search-field";
export { SearchField, type SearchFieldComposedProps, type SearchFieldParts } from "./composed";
export {
  type SearchFieldApi,
  SearchFieldCancelTrigger,
  SearchFieldClearTrigger,
  SearchFieldControl,
  SearchFieldField,
  SearchFieldIndicator,
  SearchFieldRoot,
  type SearchFieldRootProps,
  type UseSearchFieldProps,
  useSearchField,
  useSearchFieldContext,
} from "./search-field";

/**
 * The search field: the `search` landmark, the capsule inside it, the native
 * searchbox inside that, and the decorations that belong to the presentation —
 * the magnifier, the clear button, and the cancel button that stands *beside*
 * the capsule rather than in it.
 *
 * `SearchFieldRoot` is the row and `SearchFieldField` is the box. They were one
 * element until 2026-09-05; splitting them is what lets the cancel button be a
 * sibling of the capsule instead of a passenger inside it, which is the only
 * arrangement the touch layout draws. A tree without the capsule
 * still renders — and renders unstyled, which is the migration to watch for.
 *
 * Nothing here is a variant of `<InputRoot type="search">`: the machine is its
 * own, because Escape-clears, the clear gesture that hands the focus back and
 * the opt-in shortcut are behaviours a text field does not have. What the two do
 * share — the field box, the ring, the three shapes — is shared through the
 * tokens rather than through a common component, which is where sharing costs
 * nothing at runtime.
 *
 * The `field` inheritance is automatic: like every other control, the root reads
 * the field context for the ids and the states it must wear.
 */

import * as searchField from "@standarui/core/search-field";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type SearchFieldApi = searchField.SearchFieldApi<ReactPropTypes>;

const SearchFieldContext = createPartContext<SearchFieldApi>("SearchField");

export interface UseSearchFieldProps
  extends searchField.SearchFieldMachineProps,
    MachineRuntimeProps {}

export function useSearchField(props: UseSearchFieldProps): SearchFieldApi {
  return searchField.connect(useMachine(searchField.machine, props), normalizeProps);
}

/** The api of the field a subtree sits in — a consumer's own part reads it. */
export function useSearchFieldContext(): SearchFieldApi {
  return SearchFieldContext.usePart("SearchFieldContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "value",
  "defaultValue",
  "shape",
  "placeholder",
  "disabled",
  "invalid",
  "readOnly",
  "required",
  "name",
  "form",
  "autoComplete",
  "inputMode",
  "maxLength",
  "describedBy",
  "label",
  "clearLabel",
  "cancelLabel",
  "clearOnEscape",
  "hotkey",
  "onValueChange",
  "onCancel",
] as const;

export interface SearchFieldRootProps
  extends UseSearchFieldProps,
    PartProps<"div", UseSearchFieldProps> {}

export function SearchFieldRoot(props: SearchFieldRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();

  const api = useSearchField({
    ...inheritFromField(machineProps, field),
    ids: { control: field?.controlProps.id, ...machineProps.ids },
  });

  return (
    <SearchFieldContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </SearchFieldContext.Provider>
  );
}

/**
 * The capsule. Everything the field *looks* like is here — the box, the border,
 * the radius, the ring, the read-only wash — and the row above it holds nothing
 * but the layout and the landmark.
 */
export const SearchFieldField: (props: PartProps<"div">) => ReactNode = createPart(
  SearchFieldContext,
  {
    name: "SearchFieldField",
    element: "div",
    props: (api) => api.getFieldProps(),
  },
);

/** Decorative by contract: put an inline SVG in it, never a text glyph. */
export const SearchFieldIndicator: (props: PartProps<"span">) => ReactNode = createPart(
  SearchFieldContext,
  {
    name: "SearchFieldIndicator",
    element: "span",
    props: (api) => api.getIndicatorProps(),
  },
);

export const SearchFieldControl: (props: PartProps<"input">) => ReactNode = createPart(
  SearchFieldContext,
  {
    name: "SearchFieldControl",
    element: "input",
    props: (api) => api.getControlProps(),
  },
);

export const SearchFieldClearTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  SearchFieldContext,
  {
    name: "SearchFieldClearTrigger",
    element: "button",
    props: (api) => api.getClearTriggerProps(),
  },
);

/**
 * A sibling of the capsule, not a child of it — the whole reason the parts were
 * split. It is a real tab stop with a name of its own, so the sheet may draw its
 * glyph; leave it empty and it gets a ✕.
 */
export const SearchFieldCancelTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  SearchFieldContext,
  {
    name: "SearchFieldCancelTrigger",
    element: "button",
    props: (api) => api.getCancelTriggerProps(),
  },
);
